import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"EmakiStructure","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/structure/index.md","filePath":"en/modules/structure/index.md","lastUpdated":0}`),a={name:`en/modules/structure/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="emakistructure" tabindex="-1">EmakiStructure <a class="header-anchor" href="#emakistructure" aria-label="Permalink to “EmakiStructure”">​</a></h1><p>EmakiStructure is a structure generation and multiblock interaction module. It lets server owners select a region and export <code>.nbt</code> structure templates for oriented placement, record and trigger multiblock structure definitions, roll back interrupted generation, intercept-replace vanilla structures in not-yet-generated chunks, and identify and restore furniture from four sources (ItemsAdder / Oraxen / Nexo / CraftEngine)</p><h2 id="basics" tabindex="-1">Basics <a class="header-anchor" href="#basics" aria-label="Permalink to “Basics”">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Value</th></tr></thead><tbody><tr><td>Module version</td><td><code>1.0.4</code></td></tr><tr><td>Build artifact</td><td><code>EmakiStructure-1.0.4.jar</code></td></tr><tr><td>API coordinate</td><td><code>emaki.jiuwu.craft:emaki-structure-api:1.0.1</code> (<code>compileOnly</code> only; never dropped into <code>plugins/</code>)</td></tr><tr><td>Root command</td><td><code>/emakistructure</code> (aliases <code>/ems</code>, <code>/estruct</code>)</td></tr><tr><td>Hard dependency</td><td>EmakiCoreLib (<code>required: true</code>)</td></tr><tr><td>Soft dependencies</td><td>MythicMobs, EmakiMobs, ItemsAdder, Oraxen, Nexo, CraftEngine (all <code>required: false</code>; the matching capability degrades when absent)</td></tr><tr><td>Permission nodes</td><td><code>emakistructure.use</code>, <code>emakistructure.edit</code>, <code>emakistructure.reload</code>, <code>emakistructure.admin</code></td></tr><tr><td>Descriptor baseline</td><td><code>api-version: &quot;1.21.8&quot;</code>, <code>folia-supported: true</code></td></tr></tbody></table><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>EmakiStructure is a <code>.key</code>-gated private module: it takes part in the default build only when a <code>.key</code> file exists at the repository root</p></div><h2 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to “Pages”">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Contents</th></tr></thead><tbody><tr><td><a href="./commands.html">Commands &amp; Permissions</a></td><td>Selection, export, placement, multiblock, and debug commands</td></tr><tr><td><a href="./templates.html">Structure Templates</a></td><td>Selection highlight, <code>.nbt</code> import/export validation, spawn and furniture sidecars</td></tr><tr><td><a href="./multiblocks.html">Multiblock Structures</a></td><td><code>multiblocks/*.yml</code> definitions, triggers, and incremental detection</td></tr><tr><td><a href="./configuration.html">Configuration</a></td><td>Every <code>config.yml</code> key</td></tr><tr><td><a href="./api.html">API &amp; Integration</a></td><td>The <code>emaki-structure-api</code> facade and <code>MultiblockTriggerEvent</code></td></tr></tbody></table><h2 id="core-capabilities" tabindex="-1">Core capabilities <a class="header-anchor" href="#core-capabilities" aria-label="Permalink to “Core capabilities”">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Description</th></tr></thead><tbody><tr><td>Two-corner selection</td><td><code>/ems select pos1/pos2</code> to set corners, <code>adjust</code> to nudge, <code>clear</code> to reset; the region is outlined by a continuous glowing wireframe</td></tr><tr><td>Structure templates</td><td>Export a selection to <code>structures/&lt;name&gt;.nbt</code> and place it by facing (including mirror variants); imports are validated per file for size, palette, and block-entity payload</td></tr><tr><td>Generation guardrails</td><td>Per-tick write cap, TPS-adaptive throttling, queue timeout, ground support policy (<code>skip</code>/<code>keep</code>/<code>fill</code>), and player-trapped detection</td></tr><tr><td>Transaction rollback</td><td>When generation is interrupted (reload / stop / timeout / limit), a delta snapshot restores the area to its pre-generation state; uncommitted transactions are cleaned up at startup</td></tr><tr><td>Vanilla structure replacement</td><td><code>replace_rules</code> replaces vanilla structures (villages, etc.) in not-yet-generated chunks with your own template; already-generated chunks are never rewritten</td></tr><tr><td>Multiblock structures</td><td>Record a layout to <code>multiblocks/&lt;id&gt;.yml</code>; when a player assembles the shape, the configured actions run. Supports shape validation, cooldown, conditions, and incremental detection</td></tr><tr><td>Four-source furniture</td><td>Export recognizes ItemsAdder / Oraxen / Nexo / CraftEngine furniture into <code>furniture/&lt;template&gt;.yml</code>, restores it on placement by facing, and removes it during rollback</td></tr><tr><td>In-structure mobs</td><td><code>spawns/&lt;template&gt;.yml</code> sidecars spawn mobs from points/spheres/regions (<code>minecraft:</code> / <code>mythicmobs:</code> / <code>emakimobs:</code> prefixes)</td></tr></tbody></table><h2 id="default-data-directory" tabindex="-1">Default data directory <a class="header-anchor" href="#default-data-directory" aria-label="Permalink to “Default data directory”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/EmakiStructure/</span></span>
<span class="line"><span>├── config.yml</span></span>
<span class="line"><span>├── structures/           ← .nbt structure templates (structure export output)</span></span>
<span class="line"><span>├── multiblocks/          ← multiblock definitions (multiblock export output)</span></span>
<span class="line"><span>├── spawns/               ← in-structure mob spawn sidecars</span></span>
<span class="line"><span>├── furniture/            ← furniture restoration sidecars (written on export)</span></span>
<span class="line"><span>├── journal/              ← generation transaction rollback logs (runtime files)</span></span>
<span class="line"><span>├── replaced/             ← vanilla replacement markers (runtime files)</span></span>
<span class="line"><span>└── lang/</span></span></code></pre></div><p><code>structures/</code> and <code>multiblocks/</code> come from in-game commands but may be written by hand; <code>spawns/</code> and <code>furniture/</code> are authored manually. <code>journal/</code> and <code>replaced/</code> are runtime files — do not edit them. Files take effect after <code>/ems reload</code></p><h2 id="typical-workflow" tabindex="-1">Typical workflow <a class="header-anchor" href="#typical-workflow" aria-label="Permalink to “Typical workflow”">​</a></h2><ol><li><code>/ems select pos1</code> then <code>/ems select pos2</code> and confirm the reported size</li><li><code>/ems structure export &lt;name&gt;</code> to write <code>structures/&lt;name&gt;.nbt</code></li><li>(Optional) author <code>spawns/&lt;name&gt;.yml</code> for mob spawns; furniture sidecars are written automatically when the selection contained furniture-plugin blocks</li><li><code>/ems get &lt;name&gt; [facing]</code> to preview, or <code>/ems structure place &lt;name&gt; &lt;facing&gt;</code> to place for real</li><li>Multiblocks: <code>/ems multiblock export &lt;id&gt;</code> records the layout, and the actions fire once players assemble it</li><li>For vanilla structure replacement, declare entries under <code>replace_rules</code> in <code>config.yml</code></li></ol><h2 id="relation-to-other-modules" tabindex="-1">Relation to other modules <a class="header-anchor" href="#relation-to-other-modules" aria-label="Permalink to “Relation to other modules”">​</a></h2><table tabindex="0"><thead><tr><th>Module</th><th>Collaboration</th></tr></thead><tbody><tr><td>EmakiCoreLib</td><td>Hard dependency: dispatcher, debug command, messages, and config precheck infrastructure; multiblock trigger actions run through the CoreLib action pipeline</td></tr><tr><td>EmakiMobs / MythicMobs</td><td>The <code>spawns/</code> sidecar can spawn <code>emakimobs:</code> / <code>mythicmobs:</code> custom mobs (both optional)</td></tr><tr><td>ItemsAdder / Oraxen / Nexo / CraftEngine</td><td>Optional furniture and custom-block sources; matching entries are skipped with a warning when absent</td></tr></tbody></table>`,16)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};